\begin{array}{l} \left| \begin{array}{c c c c c c} \binom {r} {r - 1} & \binom {r} {r} & 0 & \dots & 0 & 0 \\ \binom {r + 1} {r - 1} & \binom {r + 1} {r} & \binom {r + 1} {r + 1} & \dots & 0 & 0 \\ \vdots & \vdots & \vdots & & \vdots & \vdots \\ \binom {n - 3} {r - 1} & \binom {n - 3} {r} & \binom {n - 3} {r + 1} & \dots & \binom {n - 3} {n - 3} & 0 \\ \binom {n - 2} {r - 1} & \binom {n - 2} {r} & \binom {n - 2} {r + 1} & \dots & \binom {n - 2} {n - 3} & \binom {n - 2} {n - 2} \\ \binom {n - 1} {r - 1} & \binom {n - 1} {r} & \binom {n - 1} {r + 1} & \dots & \binom {n - 1} {n - 3} & \binom {n - 1} {n - 2} \end{array} \right| + \left| \begin{array}{c c c c c c} \binom {r} {r} & 0 & 0 & \dots & 0 & 0 \\ \binom {r + 1} {r - 1} & \binom {r + 1} {r} & \binom {r + 1} {r + 1} & \dots & 0 & 0 \\ \vdots & \vdots & \vdots & & \vdots & \vdots \\ \binom {n - 3} {r - 1} & \binom {n - 3} {r} & \binom {n - 3} {r + 1} & \dots & \binom {n - 3} {n - 3} & 0 \\ \binom {n - 2} {r - 1} & \binom {n - 2} {r} & \binom {n - 2} {r + 1} & \dots & \binom {n - 2} {n - 3} & \binom {n - 2} {n - 2} \\ \binom {n - 1} {r - 1} & \binom {n - 1} {r} & \binom {n - 1} {r + 1} & \dots & \binom {n - 1} {n - 3} & \binom {n - 1} {n - 2} \end{array} \right| \\ = D (n - 1, r - 1) + D (n - 1, r). \\ \end{array}
